<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentityRef;

final class ClientIdentityRefUnitTest extends TestCase
{
    public function test(): void
    {
        $uid = 'uid';
        $ref = new ClientIdentityRef(uid: $uid);
        $this->assertSame($uid, $ref->uid());
    }
}
